const ai = $('Ollama').first().json.response;
let d;
try { d = JSON.parse(ai.match(/\{[\s\S]*\}/)[0]); } catch(e) { throw new Error('Bad JSON'); }
const gv = (val) => { if (!val || String(val).trim() === '' || String(val).toLowerCase() === 'null' || String(val).toLowerCase() === 'none') return 'No disponible'; return String(val).trim(); };
let rN = gv(d.factura_numero);
let rF = gv(d.factura_fecha);
const fD = (s) => { if (s === 'No disponible') return s; let clean = s.replace(/[^0-9\-\/\.]/g, ''); const p = clean.split(/[\-\/\.]/); if (p.length >= 3) { let y, m, d; if (p[0].length === 4) { y = p[0]; m = p[1]; d = p[2]; } else { d = p[0]; m = p[1]; y = p[2]; } if (y.length === 2) y = '20' + y; return d.padStart(2,'0') + '/' + m.padStart(2,'0') + '/' + y; } return s; };
let eN = gv(d.empresa_nombre), eC = gv(d.empresa_cif), eD = gv(d.empresa_direccion), eT = gv(d.empresa_telefono);
let cN = gv(d.cliente_nombre), cC = gv(d.cliente_cif), cDir = gv(d.cliente_direccion);
const isClient = (name) => /innovatek|alejandro|calvo|yuniq/i.test(name);
if (isClient(eN) && !isClient(cN)) { let tmp = eN; eN = cN; cN = tmp; tmp = eC; eC = cC; cC = tmp; tmp = eD; eD = cDir; cDir = tmp; }
let base = parseFloat(String(d.base_imponible_total).replace(',','.')) || 0;
let iva = parseFloat(String(d.iva_total).replace(',','.')) || 0;
let total = parseFloat(String(d.total_factura).replace(',','.')) || 0;
if (total === 0 && (base > 0 || iva > 0)) { total = base + iva; } else if (Math.abs((base + iva) - total) > 0.05) { if (base + iva > 0) total = base + iva; }
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const q = String.fromCharCode(34);
const c = (t, v) => '<ss:Cell><ss:Data ss:Type=' + q + t + q + '>' + v + '</ss:Data></ss:Cell>';
let row = '<ss:Row>';
row += c('String', esc(rN));
row += c('String', esc(fD(rF)));
row += c('String', esc(eN));
row += c('String', esc(eC));
row += c('String', esc(eD));
row += c('String', esc(eT));
row += c('String', esc(cN));
row += c('String', esc(cC));
row += c('String', esc(cDir));
row += c('Number', String(base));
row += c('Number', String(iva));
row += c('Number', String(total));
row += c('String', esc(gv(d.cuenta_bancaria_iban)));
row += c('String', esc(gv(d.metodo_pago)));
row += '</ss:Row>';
let xml = '';
try { const b = await this.helpers.getBinaryDataBuffer(0, 'data'); if (b) xml = b.toString('utf-8'); } catch(e) {}
if (xml && xml.includes('>' + esc(rN) + '</ss:Data>')) { return [{ json: { success: false, reason: 'Duplicate', file: $('Bucle').first().json.path }, binary: { data: await this.helpers.getBinaryDataBuffer(0, 'data') } }]; }
const re = /(<\/(?:ss:)?Table\s*>)/i;
if (xml && re.test(xml)) { xml = xml.replace(re, row + '\n$1'); } else {
  const hc = (t) => '<ss:Cell ss:StyleID=' + q + 'header' + q + '><ss:Data ss:Type=' + q + 'String' + q + '>' + t + '</ss:Data></ss:Cell>';
  const hdr = '<ss:Row ss:Height=' + q + '30' + q + '>' + hc('N Factura') + hc('Fecha') + hc('Empresa') + hc('CIF/NIF Empresa') + hc('Dir Empresa') + hc('Tel Empresa') + hc('Cliente') + hc('CIF/NIF Cliente') + hc('Dir Cliente') + hc('Base Imponible') + hc('IVA') + hc('Total') + hc('IBAN') + hc('Método Pago') + '</ss:Row>';
  xml = '<?xml version=' + q + '1.0' + q + ' encoding=' + q + 'UTF-8' + q + '?><?mso-application progid=' + q + 'Excel.Sheet' + q + '?><Workbook xmlns=' + q + 'urn:schemas-microsoft-com:office:spreadsheet' + q + ' xmlns:ss=' + q + 'urn:schemas-microsoft-com:office:spreadsheet' + q + '><Styles><Style ss:ID=' + q + 'Default' + q + '><Font ss:FontName=' + q + 'Calibri' + q + ' ss:Size=' + q + '11' + q + '/></Style><Style ss:ID=' + q + 'header' + q + '><Font ss:Bold=' + q + '1' + q + ' ss:Color=' + q + '#FFFFFF' + q + ' ss:FontName=' + q + 'Calibri' + q + ' ss:Size=' + q + '11' + q + '/><Interior ss:Color=' + q + '#1F4E79' + q + ' ss:Pattern=' + q + 'Solid' + q + '/></Style></Styles><Worksheet ss:Name=' + q + 'Facturas' + q + '><Table>' + hdr + row + '</Table></Worksheet></Workbook>';
}
return [{ json: { success: true, file: $('Bucle').first().json.path }, binary: { data: { data: Buffer.from(xml, 'utf-8').toString('base64'), mimeType: 'application/vnd.ms-excel', fileName: 'tabla_excell_facturas.xls', fileExtension: 'xls' } } }];
